using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;
[InitializeOnLoad]public static class RoadPropsEmissionSetup{static RoadPropsEmissionSetup(){EditorApplication.update+=Run;}static void Run(){if(EditorApplication.isCompiling||!File.Exists("RoadPropsEmissionSetup.request"))return;File.Delete("RoadPropsEmissionSetup.request");try{var m=AssetDatabase.LoadAssetAtPath<Material>("Assets/Scenes/Oasis/3D/Fbx/Materials/Roads Props 01.mat");var map=AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/Scenes/Oasis/3D/Texture/Roads Props/Emmision.jpg");if(!m||!map)throw new Exception("Existing road props material or emission map missing");AssetDatabase.ImportAsset(AssetDatabase.GetAssetPath(m.shader),ImportAssetOptions.ForceUpdate);m.SetTexture("_EmissionMap",map);m.SetColor("_EmissionColor",Color.white);m.SetFloat("_UseEmissionMap",1);m.SetFloat("_EmissionStrength",4);m.SetFloat("_EmissionNightOnly",1);m.EnableKeyword("_ARTWORK_EMISSION_MAP");m.enableInstancing=true;EditorUtility.SetDirty(m);AssetDatabase.SaveAssets();if(ShaderUtil.ShaderHasError(m.shader))throw new Exception("Emission shader errors");var sc=SceneManager.GetActiveScene();var all=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Renderer>(true)).Where(r=>r.sharedMaterials.Contains(m)).ToArray();var c=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<CityDayNightController>(true)).First();bool night=c.IsNight;try{c.Apply(true);var view=SceneView.lastActiveSceneView;if(view&&view.camera){var cap=typeof(CityTaxiStandBuild).GetMethod("Capture",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic);cap.Invoke(null,new object[]{sc,view.camera.transform.position,view.camera.transform.position+view.camera.transform.forward*30,"Road-Props-Emission"});}}finally{c.Apply(night);}File.WriteAllText("FinalEnvironmentRoadReview/RoadPropsEmission.txt","SUCCESS: Existing Roads Props 01 material uses existing Roads Props/Emmision.jpg (identical to supplied file). Emission map, HDR tint, brightness, enable and night-only controls exposed. Existing lamp pixels emit; black pixels unlit. Optional shader keyword keeps other artwork materials on previous path, with no extra sample when disabled. No new materials, textures, meshes or realtime lights. Instancing retained. Shader errors=0. Matching renderers="+all.Length); }catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/RoadPropsEmission.txt",e.ToString());Debug.LogException(e);}}}
